class Solution {
public:
    int maxProfit(vector<int>& prices, vector<int>& profits) {
        int n = prices.size(), ans = -1;
        for (int j = 0; j < n; j++) {
            int left_max = -1;
            for (int i = 0; i < j; i++) {
                if (prices[i] < prices[j]) left_max = max(left_max, profits[i]);
            }
            int right_max = -1;
            for (int k = j + 1; k < n; k++) {
                if (prices[k] > prices[j]) right_max = max(right_max, profits[k]);
            }
            if (left_max != -1 && right_max != -1) {
                ans = max(ans, left_max + profits[j] + right_max);
            }
        }
        return ans;
    }
};

class Solution {
    public int maxProfit(int[] prices, int[] profits) {
        int n = prices.length, ans = -1;
        for (int j = 0; j < n; j++) {
            int leftMax = -1;
            for (int i = 0; i < j; i++) {
                if (prices[i] < prices[j]) leftMax = Math.max(leftMax, profits[i]);
            }
            int rightMax = -1;
            for (int k = j + 1; k < n; k++) {
                if (prices[k] > prices[j]) rightMax = Math.max(rightMax, profits[k]);
            }
            if (leftMax != -1 && rightMax != -1) {
                ans = Math.max(ans, leftMax + profits[j] + rightMax);
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} prices
 * @param {number[]} profits
 * @return {number}
