var maxProfit = function(prices, profits) {
    const n = prices.length;
    let ans = -1;
    for (let j = 0; j < n; j++) {
        let leftMax = -1;
        for (let i = 0; i < j; i++) {
            if (prices[i] < prices[j] && profits[i] > leftMax) leftMax = profits[i];
        }
        let rightMax = -1;
        for (let k = j + 1; k < n; k++) {
            if (prices[k] > prices[j] && profits[k] > rightMax) rightMax = profits[k];
        }
        if (leftMax !== -1 && rightMax !== -1) {
            const curr = leftMax + profits[j] + rightMax;
            if (curr > ans) ans = curr;
        }
    }
    return ans;
};
